function verify(log,inspect){
const b=Array(81).fill("."),caps={X:0,O:0};let ko=null,steps=0;const checks=[],captureEvents=[],transientKo=[];
const adj=i=>[i%9?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(j=>j>=0);
const ix=p=>(9-Number(p.slice(1)))*9+"ABCDEFGHJ".indexOf(p[0]);
const name=i=>"ABCDEFGHJ"[i%9]+(9-Math.floor(i/9));
function group(i){const seen=new Set([i]),todo=[i],lib=new Set();while(todo.length){const k=todo.pop();for(const j of adj(k)){if(b[j]===".")lib.add(j);else if(b[j]===b[i]&&!seen.has(j)){seen.add(j);todo.push(j)}}}return {stones:[...seen],lib:[...lib]}}
function apply(m){const c=m.color==="B"?"X":"O",enemy=c==="X"?"O":"X";if(m.move==="pass"){ko=null;return}const i=ix(m.move);if(b[i]!=="."||i===ko)throw Error("occupied/ko "+m.n);b[i]=c;const killed=[];for(const j of adj(i))if(b[j]===enemy){const g=group(j);if(!g.lib.length){for(const k of g.stones){b[k]=".";killed.push(k)}}}const own=group(i);if(!own.lib.length)throw Error("suicide "+m.n);caps[c]+=killed.length;if(killed.length)captureEvents.push({move:m.n,color:m.color,point:m.move,captured:killed.map(name).sort()});ko=killed.length===1&&own.stones.length===1&&own.lib.length===1?killed[0]:null;if(ko!==null)transientKo.push({after:m.n,point:name(ko)});}
for(const raw of log.raw){const t=raw.response.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");const next=Number(t.match(/Move number: (\d+)/)?.[1]);if(!next)throw Error("number missing");while(steps<next-1){apply(log.moves[steps]);steps++}const actual=inspect(raw.response);if(actual.board.join("")!==b.join(""))throw Error("board mismatch "+raw.kind);const cp=t.match(/Captured by Black: (\d+); by White: (\d+)/);if(Number(cp[1])!==caps.X||Number(cp[2])!==caps.O)throw Error("captures mismatch");const kp=t.match(/Ko point: ([A-HJ][1-9]|none)/)?.[1];if(kp!==(ko===null?"none":name(ko)))throw Error("ko mismatch");checks.push({kind:raw.kind,next,board:true,captures:true,ko:true})}
return {actualMoves:steps,rawSnapshots:checks.length,physicalCaptures:caps,captureEvents,transientKo,checks};}

